-- Bank database for nl2sql: a retail bank with branches, staff, customers, accounts,
-- debit cards, card merchants, transactions, loans with repayment schedules, and fraud alerts.
-- All amounts are in US dollars.
--
-- Written in plain SQL that runs unchanged on PostgreSQL, MySQL 8 and SQLite:
-- VARCHAR rather than TEXT (MySQL can't index TEXT), table-level FOREIGN KEY clauses
-- (MySQL ignores inline REFERENCES), dates as DATE, money as NUMERIC.
-- Seed data lives in seed.sql, generated by `python -m nl2sql.bank_db --write-sql db/bank`.

CREATE TABLE branches (
    id          INTEGER      NOT NULL PRIMARY KEY,
    name        VARCHAR(60)  NOT NULL UNIQUE,
    city        VARCHAR(60)  NOT NULL,
    state       VARCHAR(2)   NOT NULL,
    opened_on   DATE         NOT NULL
);

-- manager_id points at another employee (NULL for the chief executive).
CREATE TABLE employees (
    id          INTEGER      NOT NULL PRIMARY KEY,
    first_name  VARCHAR(50)  NOT NULL,
    last_name   VARCHAR(50)  NOT NULL,
    title       VARCHAR(60)  NOT NULL,
    branch_id   INTEGER,                   -- NULL for head-office staff
    hire_date   DATE         NOT NULL,
    manager_id  INTEGER,
    FOREIGN KEY (branch_id) REFERENCES branches (id),
    FOREIGN KEY (manager_id) REFERENCES employees (id)
);

-- kyc_status: identity checks ("know your customer"). risk_rating: anti-money-laundering risk.
CREATE TABLE customers (
    id             INTEGER      NOT NULL PRIMARY KEY,
    first_name     VARCHAR(50)  NOT NULL,
    last_name      VARCHAR(50)  NOT NULL,
    email          VARCHAR(120) NOT NULL UNIQUE,
    date_of_birth  DATE         NOT NULL,
    city           VARCHAR(60)  NOT NULL,
    state          VARCHAR(2)   NOT NULL,
    home_branch_id INTEGER      NOT NULL,
    joined_on      DATE         NOT NULL,
    kyc_status     VARCHAR(10)  NOT NULL,
    risk_rating    VARCHAR(10)  NOT NULL,
    CHECK (kyc_status IN ('verified', 'pending', 'rejected')),
    CHECK (risk_rating IN ('low', 'medium', 'high')),
    FOREIGN KEY (home_branch_id) REFERENCES branches (id)
);

-- balance always equals the sum of the account's transactions.
-- interest_rate is annual, as a fraction (0.0425 = 4.25%).
CREATE TABLE accounts (
    id             INTEGER       NOT NULL PRIMARY KEY,
    account_number VARCHAR(12)   NOT NULL UNIQUE,
    customer_id    INTEGER       NOT NULL,
    branch_id      INTEGER       NOT NULL,
    account_type   VARCHAR(10)   NOT NULL,
    status         VARCHAR(10)   NOT NULL,
    opened_on      DATE          NOT NULL,
    closed_on      DATE,
    interest_rate  NUMERIC(6,4)  NOT NULL,
    balance        NUMERIC(14,2) NOT NULL,
    CHECK (account_type IN ('checking', 'savings', 'business')),
    CHECK (status IN ('active', 'frozen', 'closed')),
    FOREIGN KEY (customer_id) REFERENCES customers (id),
    FOREIGN KEY (branch_id) REFERENCES branches (id)
);

-- Debit cards, attached to checking and business accounts.
CREATE TABLE cards (
    id          INTEGER     NOT NULL PRIMARY KEY,
    account_id  INTEGER     NOT NULL,
    last4       VARCHAR(4)  NOT NULL,
    issued_on   DATE        NOT NULL,
    expires_on  DATE        NOT NULL,
    status      VARCHAR(10) NOT NULL,
    CHECK (status IN ('active', 'blocked', 'expired')),
    FOREIGN KEY (account_id) REFERENCES accounts (id)
);

CREATE TABLE merchants (
    id          INTEGER     NOT NULL PRIMARY KEY,
    name        VARCHAR(80) NOT NULL UNIQUE,
    category    VARCHAR(20) NOT NULL,
    city        VARCHAR(60) NOT NULL,
    CHECK (category IN ('groceries', 'dining', 'travel', 'fuel', 'utilities', 'shopping',
                        'entertainment', 'health'))
);

-- amount is signed: money in is positive, money out is negative.
-- Card payments set card_id and merchant_id. Transfers come in pairs (transfer_out on one
-- account, transfer_in on the other, same day and amount), each naming the other account
-- in counterparty_account_id.
CREATE TABLE transactions (
    id                      INTEGER       NOT NULL PRIMARY KEY,
    account_id              INTEGER       NOT NULL,
    posted_on               DATE          NOT NULL,
    txn_type                VARCHAR(20)   NOT NULL,
    amount                  NUMERIC(14,2) NOT NULL,
    card_id                 INTEGER,
    merchant_id             INTEGER,
    counterparty_account_id INTEGER,
    description             VARCHAR(120)  NOT NULL,
    CHECK (txn_type IN ('deposit', 'salary', 'withdrawal', 'card_payment', 'transfer_in',
                        'transfer_out', 'fee', 'interest', 'loan_payment')),
    FOREIGN KEY (account_id) REFERENCES accounts (id),
    FOREIGN KEY (card_id) REFERENCES cards (id),
    FOREIGN KEY (merchant_id) REFERENCES merchants (id),
    FOREIGN KEY (counterparty_account_id) REFERENCES accounts (id)
);

-- officer_id: the employee who approved the loan. interest_rate is annual, as a fraction.
CREATE TABLE loans (
    id             INTEGER       NOT NULL PRIMARY KEY,
    customer_id    INTEGER       NOT NULL,
    branch_id      INTEGER       NOT NULL,
    officer_id     INTEGER       NOT NULL,
    loan_type      VARCHAR(10)   NOT NULL,
    principal      NUMERIC(14,2) NOT NULL,
    interest_rate  NUMERIC(6,4)  NOT NULL,
    term_months    INTEGER       NOT NULL,
    start_on       DATE          NOT NULL,
    status         VARCHAR(10)   NOT NULL,
    CHECK (loan_type IN ('mortgage', 'auto', 'personal', 'business')),
    CHECK (status IN ('active', 'paid_off', 'defaulted')),
    FOREIGN KEY (customer_id) REFERENCES customers (id),
    FOREIGN KEY (branch_id) REFERENCES branches (id),
    FOREIGN KEY (officer_id) REFERENCES employees (id)
);

-- One row per monthly instalment that has fallen due. paid_on is NULL for a missed payment;
-- a payment made after due_on was late.
CREATE TABLE loan_payments (
    id          INTEGER       NOT NULL PRIMARY KEY,
    loan_id     INTEGER       NOT NULL,
    due_on      DATE          NOT NULL,
    amount_due  NUMERIC(12,2) NOT NULL,
    paid_on     DATE,
    amount_paid NUMERIC(12,2) NOT NULL,
    FOREIGN KEY (loan_id) REFERENCES loans (id)
);

-- Raised by the fraud system on suspicious card payments. confirmed_fraud is NULL until reviewed.
CREATE TABLE fraud_alerts (
    id              INTEGER      NOT NULL PRIMARY KEY,
    transaction_id  INTEGER      NOT NULL UNIQUE,
    raised_on       DATE         NOT NULL,
    reason          VARCHAR(60)  NOT NULL,
    reviewed_by     INTEGER,
    confirmed_fraud BOOLEAN,
    FOREIGN KEY (transaction_id) REFERENCES transactions (id),
    FOREIGN KEY (reviewed_by) REFERENCES employees (id)
);

CREATE INDEX idx_accounts_customer ON accounts (customer_id);
CREATE INDEX idx_transactions_account ON transactions (account_id, posted_on);
CREATE INDEX idx_transactions_merchant ON transactions (merchant_id);
CREATE INDEX idx_loans_customer ON loans (customer_id);
CREATE INDEX idx_loan_payments_loan ON loan_payments (loan_id);
